["b"] = 0.250980406999588,
},
["text"] = "|Hplayer:Bidehwei Hamtoskr:1522:TEXT_EMOTE:|h|cff0070ddBidehwei Hamtoskr|r|h cries on Aamelia Windfield's shoulder.",
["timestamp"] = 1794465365,
["id"] = "s1_3602",
},
