},
["color"] = {
["r"] = 1,
["g"] = 0.501960813999176,
["b"] = 0.250980406999588,
},
["text"] = "Aamelia raises her pitchfork, ready to fight.",
["timestamp"] = 1794465901,
["id"] = "s1_3664",
},
{
["recordedBy"] = "Simondruid-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Aamelia Windfield",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Aamelia Windfield says: I'm done talking. Stranger, thanks for everything...",
