["level"] = 32,
},
["event"] = "CHAT_MSG_GUILD",
["type"] = "GUILD",
},
["color"] = {
["b"] = 0.250980406999588,
["g"] = 1,
["r"] = 0.250980406999588,
},
["text"] = "|Hchannel:GUILD|h[Guild]|h |Hplayer:Aes Bavits:1385:GUILD:|h[|cff3fc7ebAes Bavits|r]|h: GRMbrb",
["id"] = "s1_4876",
["timestamp"] = 1794543816,
},
{
["recordedBy"] = "Simonhunter-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Riaani Nightwind",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Riaani Nightwind says: Lastly, the bandit highwaymen common in the Gustberry Lowlands are known to hoard a variety of junk at their camps. Construct parts are likely to be found among such loot.",
["id"] = "s1_4877",
["timestamp"] = 1794543825,
},
{
