},
["color"] = {
["r"] = 1,
["g"] = 0.501960813999176,
["b"] = 0.250980406999588,
},
["text"] = "Aamelia raises her pitchfork, ready to fight.",
["timestamp"] = 1794544492,
["id"] = "s1_4979",
},
{
["recordedBy"] = "Simonhunter-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Aamelia Windfield",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Aamelia Windfield says: I'm done talking. Stranger, thanks for everything...",
["timestamp"] = 1794544495,
["id"] = "s1_4980",
},
{
["recordedBy"] = "Simonhunter-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Malfunctioning Cyclone Construct",
},
["event"] = "CHAT_MSG_MONSTER_YELL",
["type"] = "MONSTER_YELL",
},
["color"] = {
["r"] = 1,
["g"] = 0.250980406999588,
["b"] = 0.250980406999588,
},
["text"] = "Malfunctioning Cyclone Construct yells: THREAT DETECTED. ADMINISTERING VIOLENCE.",
["timestamp"] = 1794544498,
["id"] = "s1_4981",
},
{
["recordedBy"] = "Simonhunter-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Malfunctioning Cyclone Construct",
},
["event"] = "CHAT_MSG_MONSTER_YELL",
["type"] = "MONSTER_YELL",
},
["color"] = {
["r"] = 1,
["g"] = 0.250980406999588,
["b"] = 0.250980406999588,
},
["text"] = "Malfunctioning Cyclone Construct yells: FUNCTION FULFILLED. RESUMING REST MODE.",
["timestamp"] = 1794544505,
["id"] = "s1_4982",
},
{
["recordedBy"] = "Simonhunter-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Aamelia Windfield",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Aamelia Windfield says: Huh. Well that was... unexpected. I guess we know what that big lug's purpose is now. Let's head back to the house, stranger.",
["timestamp"] = 1794544506,
["id"] = "s1_4983",
},
